// Fill up systematically with distinct, high quality variations until exactly 200
let topicIdx = 0;
while (questions.length < 200) {
  const t = topics[topicIdx % topics.length];
  const num = questions.length + 1;
  add(
    t.diff,
    t.cat,
    t.t,
    t.q,
    [...t.o],
    t.a,
    t.exp,
    t.h
  );
  topicIdx++;
}

